<?php require_once __DIR__.'/../lib/helpers.php'; require_login(); $conn=db(); $from=$_GET['from']; $to=$_GET['to'];
$q=$conn->query("SELECT j.tanggal_bayar, p.no_pinjaman, j.hari_ke, j.bayar_nominal, j.denda FROM ksp_jadwal_angsuran j JOIN ksp_pinjaman p ON p.id=j.pinjaman_id WHERE j.status='lunas' AND j.tanggal_bayar BETWEEN '".$conn->real_escape_string($from)."' AND '".$conn->real_escape_string($to)."' ORDER BY j.tanggal_bayar"); ?><!doctype html><html><head><meta charset='utf-8'><title>Laporan Angsuran</title><style>@media print{@page{size:A4;margin:12mm}} body{font-family:Arial;font-size:11pt} table{width:100%;border-collapse:collapse} th,td{border:1px solid #333;padding:6px 8px}</style></head><body onload='window.print()'><h3>Laporan Angsuran (<?php echo htmlspecialchars($from); ?> s/d <?php echo htmlspecialchars($to); ?>)</h3><table><thead><tr><th>Tanggal</th><th>No</th><th>Hari</th><th>Bayar</th><th>Denda</th></tr></thead><tbody><?php $sum=0;$sd=0; while($r=$q->fetch_assoc()): $sum+=$r['bayar_nominal']; $sd+=$r['denda']; ?><tr><td><?php echo htmlspecialchars($r['tanggal_bayar']); ?></td><td><?php echo htmlspecialchars($r['no_pinjaman']); ?></td><td><?php echo (int)$r['hari_ke']; ?></td><td>Rp <?php echo rupiah($r['bayar_nominal']); ?></td><td>Rp <?php echo rupiah($r['denda']); ?></td></tr><?php endwhile; ?><tr><td colspan='3' style='text-align:right'><b>Total</b></td><td><b>Rp <?php echo rupiah($sum); ?></b></td><td><b>Rp <?php echo rupiah($sd); ?></b></td></tr></tbody></table></body></html>